import torch

def run(x, boundaries):
    return torch.bucketize(x, boundaries)


def run_correctness(x, boundaries):
    return torch.bucketize(x.float(), boundaries)

def gen_inputs(ctx, device):
    return {
        "boundaries": torch.tensor(
            [1.0, 3.0, 5.0, 7.0, 9.0],
            dtype=torch.float32,
            device=device,
        )
    }
